  const now = Date.now();
  const dayDiff = (d) => { if (!d || d === "unset") return 999; return Math.floor((now - new Date(d).getTime()) / 86400000); };
  const curMonth = new Date().toISOString().slice(0, 7);
  const total = state.recs.length;
  const waiting = items.length;
